      "label": "მაგიდის ნაწილობრივ დაფარული ნახვრეტი",
      "box": [381, 368, 488, 391]
    },
    {
      "id": "left_stage_clip",
      "label": "მინის მარცხენა სამაგრი",
      "box": [307, 352, 366, 375]
    },
    {
      "id": "right_stage_clip",
      "label": "მინის მარჯვენა სამაგრი",
      "box": [479, 339, 586, 392]
    },
    {
      "id": "eyepiece",
      "label": "ოკულარი",
      "box": [163, 20, 290, 110]
    },
    {
      "id": "large_focus_knob",
      "label": "დიდი გვერდითი ხრახნი",
      "box": [697, 447, 867, 549]
    },
    {
      "id": "small_focus_knob",
      "label": "პატარა გვერდითი ხრახნი",
      "box": [722, 392, 830, 454]
    }
  ],
  "steps": [
    {
      "title": "ჩართე განათება",
      "text": "დააჭირე ჩამრთველს ფუძეზე. შუქი მაგიდის ქვემოდან უნდა ანთოს.",
      "focus": ["power_switch", "illuminator"],
      "avoid": [],
      "markers": [
        {
          "part": "power_switch",
          "label": "ჩამრთველი",
          "tone": "brand"
        },
        {
          "part": "illuminator",
          "label": "განათების წყარო",
          "tone": "neutral"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "ფოტოზე განათების წყარო უკვე ანთებულს ჰგავს."
    },
    {
      "title": "დააყენე 4× ობიექტივი",
      "text": "მოატრიალე რევოლვერი, სანამ ყველაზე მოკლე ობიექტივი ქვემოთ არ დადგება და არ დაიწკაპუნებს.",
      "focus": [],
      "avoid": [],
      "markers": [
        {
          "part": "revolving_nosepiece",
          "label": "რევოლვერი",
          "tone": "neutral"
        },
        {
          "part": "right_objective",
          "label": "მოკლე ობიექტივი — გადიდება უცნობია",
          "tone": "neutral"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "ობიექტივების გადიდების წარწერები არ იკითხება, ამიტომ 4× ობიექტივი ვერ განისაზღვრება. მხოლოდ ხილული სიგრძით მისი ამოცნობა სანდო არ არის; დაწკაპუნებაც ფოტოდან ვერ დასტურდება."
    },
    {
      "title": "დადე პრეპარატი",
      "text": "მინა დადე მაგიდაზე ისე, რომ ნიმუში ზუსტად ნახვრეტის თავზე იყოს, და ორივე სამაგრით დაამაგრე.",
      "focus": [
        "glass_slide",
        "specimen_stage",
        "stage_opening",
        "left_stage_clip",
        "right_stage_clip"
      ],
      "avoid": [],
      "markers": [
        {
          "part": "glass_slide",
          "label": "საპრეპარატო მინა",
          "tone": "brand"
        },
        {
          "part": "stage_opening",
          "label": "ნახვრეტი",
          "tone": "neutral"
        },
        {
          "part": "left_stage_clip",
          "label": "მარცხენა სამაგრი",
          "tone": "brand"
        },
        {
          "part": "right_stage_clip",
          "label": "მარჯვენა სამაგრი",
          "tone": "brand"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "ფოტოზე მინა უკვე მაგიდაზეა. ნახვრეტი ნაწილობრივ დაფარულია და ნიმუშის ზუსტი ცენტრირება ფოტოდან ვერ მოწმდება."
    },
    {
      "title": "იპოვე გამოსახულება",
      "text": "ოკულარში იყურე და დიდი ხრახნი ნელა ატრიალე, სანამ გამოსახულება არ გამოჩნდება.",
      "focus": ["eyepiece", "large_focus_knob"],
      "avoid": [],
      "markers": [
        {
          "part": "eyepiece",
          "label": "ოკულარი",
          "tone": "brand"
        },
        {
          "part": "large_focus_knob",
          "label": "დიდი ხრახნი",
          "tone": "brand"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "ოკულარში მიღებული გამოსახულება ფოტოზე არ ჩანს. ფოკუსირებისას ობიექტივი მინას არ უნდა შეეხოს."
    },
    {
      "title": "გადადი 40×-ზე",
      "text": "ჩართე 40× ობიექტივი და სიმკვეთრე მხოლოდ პატარა ხრახნით დაარეგულირე, ნახევარი ბრუნით.",
      "focus": [],
      "avoid": ["large_focus_knob"],
      "markers": [
        {
          "part": "small_focus_knob",
          "label": "პატარა ხრახნი",
          "tone": "brand"
        },
        {
          "part": "large_focus_knob",
          "label": "დიდ ხრახნს არ შეეხო",
          "tone": "danger"
        }
      ],
      "arrows": [],
      "tools": [],
      "warn": "გადიდების წარწერები არ იკითხება, ამიტომ 40× ობიექტივი ვერ განისაზღვრება. ნახევარი ბრუნი ინსტრუქციაში მოცემული ზომაა და მისი საჭიროება ან საკმარისობა ფოტოდან არ დასტურდება."
    }
  ],
  "unknown_parts": [
    "4× ობიექტივი — ხილულ ობიექტივებზე გადიდების წარწერები არ იკითხება; კონკრეტულ ობიექტივთან შესაბამისობა დაუდგენელია.",
    "40× ობიექტივი — ხილულ ობიექტივებზე გადიდების წარწერები არ იკითხება; კონკრეტულ ობიექტივთან შესაბამისობა დაუდგენელია."
  ]
}
